using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Text;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

string fileId = Convert.ToString(Dynamic.FileId);
string installPath = Convert.ToString(Dynamic.InstallPath);
string addonDir = Path.Combine(ThisService.RootDirectory, "garrysmod", "addons", fileId);

if (string.IsNullOrEmpty(installPath) || !Directory.Exists(installPath))
{
    ScriptConsole.WriteLine((object)$"Nothing was downloaded for workshop file {fileId}: {installPath} does not exist.");
    return;
}

string[] downloaded = Directory.GetFiles(installPath, "*", SearchOption.AllDirectories);
if (downloaded.Length == 0)
    throw new InvalidOperationException($"Workshop file {fileId} left no files in {installPath}.");

string payload = downloaded.FirstOrDefault(f => f.EndsWith(".gma", StringComparison.OrdinalIgnoreCase))
    ?? downloaded.FirstOrDefault(f => f.EndsWith(".gm", StringComparison.OrdinalIgnoreCase))
    ?? downloaded.OrderByDescending(f => new FileInfo(f).Length).First();

if (payload.EndsWith(".gm", StringComparison.OrdinalIgnoreCase))
{
    string renamed = payload + "a";
    if (File.Exists(renamed))
        File.Delete(renamed);
    File.Move(payload, renamed);
    payload = renamed;
}

if (!payload.EndsWith(".gma", StringComparison.OrdinalIgnoreCase))
{
    Directory.CreateDirectory(addonDir);
    string loosePath = Path.Combine(addonDir, Path.GetFileName(payload));
    File.Move(payload, loosePath, true);
    ScriptConsole.WriteLine((object)$"{Path.GetFileName(payload)} is not an addon archive; installed as-is to {loosePath}.");
    return;
}

byte[] magic = ReadMagic(payload);
if (!IsGmad(magic))
{
    // Some workshop items arrive as an LZMA-alone wrapper around the real GMAD payload.
    ScriptConsole.WriteLine("Addon is compressed. Decompressing...");
    DecompressLzmaInPlace(payload);
    magic = ReadMagic(payload);
    if (!IsGmad(magic))
        throw new InvalidDataException($"{payload} is not a Garry's Mod addon. First bytes: {BitConverter.ToString(magic)}");
}

Directory.CreateDirectory(addonDir);
int extractedCount = ExtractGma(payload, addonDir);
File.Delete(payload);
ScriptConsole.WriteLine((object)$"Workshop file {fileId}: extracted {extractedCount} files to {addonDir}.");

byte[] ReadMagic(string path)
{
    using var stream = File.OpenRead(path);
    byte[] buffer = new byte[4];
    return stream.Read(buffer, 0, buffer.Length) == buffer.Length ? buffer : Array.Empty<byte>();
}

bool IsGmad(byte[] header)
{
    return header.Length == 4 && header[0] == (byte)'G' && header[1] == (byte)'M' && header[2] == (byte)'A' && header[3] == (byte)'D';
}

void DecompressLzmaInPlace(string path)
{
    string tempPath = path + ".tmp";
    try
    {
        using (var input = File.OpenRead(path))
        {
            if (input.Length < 13)
                throw new InvalidDataException($"{path} is too small to be an LZMA stream.");

            byte[] properties = new byte[5];
            byte[] sizeBytes = new byte[8];
            input.ReadExactly(properties, 0, properties.Length);
            input.ReadExactly(sizeBytes, 0, sizeBytes.Length);

            long uncompressedSize = BitConverter.ToInt64(sizeBytes, 0);
            if (uncompressedSize < 0)
                throw new InvalidDataException($"{path} declares an unknown uncompressed size, which the LZMA decoder cannot handle.");

            var decoder = new SevenZip.Compression.LZMA.Decoder();
            decoder.SetDecoderProperties(properties);
            using var output = File.Create(tempPath);
            decoder.Code(input, output, input.Length - input.Position, uncompressedSize, null);
        }

        File.Move(tempPath, path, true);
    }
    finally
    {
        if (File.Exists(tempPath))
            File.Delete(tempPath);
    }
}

string ReadNullTerminatedString(BinaryReader reader)
{
    var bytes = new List<byte>();
    byte current;
    while ((current = reader.ReadByte()) != 0)
        bytes.Add(current);
    return Encoding.UTF8.GetString(bytes.ToArray());
}

int ExtractGma(string gmaPath, string destinationDir)
{
    using var stream = File.OpenRead(gmaPath);
    using var reader = new BinaryReader(stream);

    byte[] ident = reader.ReadBytes(4);
    byte formatVersion = reader.ReadByte();
    if (formatVersion > 3)
        throw new InvalidDataException($"{gmaPath} uses GMA format version {formatVersion}, which this script cannot read.");

    long steamId = reader.ReadInt64();
    long timestamp = reader.ReadInt64();

    if (formatVersion > 1)
        while (ReadNullTerminatedString(reader).Length > 0) { } // an empty string terminates the required-content list

    string addonName = ReadNullTerminatedString(reader);
    string addonDescription = ReadNullTerminatedString(reader);
    string addonAuthor = ReadNullTerminatedString(reader);
    int addonVersion = reader.ReadInt32();

    var entries = new List<KeyValuePair<string, long>>();
    while (reader.ReadUInt32() != 0)
    {
        string entryName = ReadNullTerminatedString(reader);
        long entrySize = reader.ReadInt64();
        uint entryCrc = reader.ReadUInt32();
        entries.Add(new KeyValuePair<string, long>(entryName, entrySize));
    }

    string root = Path.GetFullPath(destinationDir);
    string rootPrefix = root + Path.DirectorySeparatorChar;
    byte[] buffer = new byte[81920];

    foreach (var entry in entries)
    {
        ThisCancellationToken.ThrowIfCancellationRequested();

        if (Path.IsPathRooted(entry.Key))
            throw new InvalidDataException($"Addon {gmaPath} contains a rooted entry '{entry.Key}'. Refusing to extract it.");

        string destination = Path.GetFullPath(Path.Combine(root, entry.Key));
        if (!destination.StartsWith(rootPrefix, StringComparison.Ordinal))
            throw new InvalidDataException($"Addon {gmaPath} contains an entry '{entry.Key}' that escapes {destinationDir}. Refusing to extract it.");

        Directory.CreateDirectory(Path.GetDirectoryName(destination));

        using var output = File.Create(destination);
        long remaining = entry.Value;
        while (remaining > 0)
        {
            int read = stream.Read(buffer, 0, (int)Math.Min(buffer.Length, remaining));
            if (read == 0)
                throw new EndOfStreamException($"{gmaPath} ended while reading '{entry.Key}'.");
            output.Write(buffer, 0, read);
            remaining -= read;
        }
    }

    return entries.Count;
}

using System;
using System.IO;

var Globals = new TCAdmin.Scripting.Engines.Addons.CSharpGameGlobals(); // DO NOT MODIFY THIS LINE

string fileId = Convert.ToString(Dynamic.FileId);
string addonsRoot = Path.Combine(ThisService.RootDirectory, "garrysmod", "addons");

if (string.IsNullOrWhiteSpace(fileId))
{
    ScriptConsole.WriteLine("No workshop file id was supplied; nothing to remove.");
    return;
}

// Anything but a plain folder name would let the recursive delete land on the addons root and wipe every addon.
if (Path.IsPathRooted(fileId)
    || fileId.IndexOfAny(new char[] { '/', '\\' }) >= 0
    || fileId.Contains("..", StringComparison.Ordinal))
    throw new InvalidOperationException($"Refusing to uninstall: workshop file id '{fileId}' is not a plain folder name.");

string addonDir = ResolveUnderAddons(addonsRoot, fileId);
string looseGma = ResolveUnderAddons(addonsRoot, fileId + ".gma");

bool removedFolder = Directory.Exists(addonDir);
if (removedFolder)
    Directory.Delete(addonDir, true);

bool removedArchive = File.Exists(looseGma);
if (removedArchive)
    File.Delete(looseGma);

if (removedFolder && removedArchive)
    ScriptConsole.WriteLine((object)$"Removed addon folder {addonDir} and leftover archive {looseGma}.");
else if (removedFolder)
    ScriptConsole.WriteLine((object)$"Removed addon folder {addonDir}.");
else if (removedArchive)
    ScriptConsole.WriteLine((object)$"Removed leftover archive {looseGma}.");
else
    ScriptConsole.WriteLine((object)$"Workshop file {fileId} left nothing behind in {addonsRoot}.");

string ResolveUnderAddons(string addonsDirectory, string name)
{
    string resolved = Path.GetFullPath(Path.Combine(addonsDirectory, name));
    string prefix = Path.GetFullPath(addonsDirectory) + Path.DirectorySeparatorChar;
    if (!resolved.StartsWith(prefix, StringComparison.Ordinal))
        throw new InvalidOperationException($"Refusing to uninstall '{name}': it resolves to {resolved}, outside {addonsDirectory}.");
    return resolved;
}
